--  DDL for Trigger TRIG_MEMBER_WITHDRAWAL
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE TRIGGER "ADMIN"."TRIG_MEMBER_WITHDRAWAL" 
            after
         update on member   
            for each row
    begin
                if :new.withdrawal = 'Y' then
                delete from
                    authority
                where
                    member_id = :new.member_id; 

                delete from
                    wish_product
                where
                    member_id = :new.member_id;

               update used_product
               set
                    is_delete = 'Y'
               where
                       seller_id =  :new.member_id;

            end if; 
            end;


/
ALTER TRIGGER "ADMIN"."TRIG_MEMBER_WITHDRAWAL" ENABLE;
