--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE TRIGGER "ADMIN"."TRIG_USED_PRODUCT_TRANSACTION_DATE" 
            after
         update on used_product   
            for each row
        begin
            if :new.TRANSACTION_DATE is not null then
            delete from
                wish_product
            where
                product_no = :new.product_no;  
        end if; 
        end;

